struct FromFileTestInfo {
  std::string sub_path;
  std::string filename;

  friend std::ostream& operator<<(std::ostream& os, const FromFileTestInfo& info) {
    return os << info.sub_path << "/" << info.filename;
  }
};

//
// File driven parameterized test support
//

using CompileToVulkanSpirv =
    ShaderCompilerTest<::testing::TestWithParam<FromFileTestInfo>>;

TEST_P(CompileToVulkanSpirv, FromFile) {
  auto const& info = GetParam();
  EXPECT_NO_THROW(loadBuilderFileCompileAndCheck(tests_path + info.sub_path + "/Inputs/",
                                                 tests_path + info.sub_path + "/Results/",
                                                 info.filename))
      << info.filename;
}

